def choose_path(answers, policy, context):
    if not context.permission_ok:
        return "stop"
    if not policy.validated_for_current_version:
        return "human_review"
    if context.high_risk or context.budget_exhausted:
        return "human_review"
    if answers["supported"]["noul"] < policy.support_floor:
        return "retrieve_more"
    return "verify_before_answer"
